func (s Scalars) JSONSize() int {
	size := 546
	size += ggen.AnySize(s.Any)
	if s.Om != "" {
		size += 8
		size += len(s.Om) * 2
	}
	if s.PI == nil {
		size += 4
	} else if (*s.PI) == nil {
		size += 4
	} else {
		size += 20
	}
	if s.PS == nil {
		size += 4
	} else {
		size += 2
		size += len((*s.PS)) * 2
	}
	if n := len(s.Raw); n > 0 {
		size += n
	} else {
		size += 4
	}
	size += len(s.Req) * 2
	size += len(string(s.Role)) * 2
	size += len(s.S) * 2
	size += len(string(s.St)) * 2
	return size
}

