func (s Stdlib) JSONSize() int {
	size := 531
	if s.Addr.Is4() {
		size += 15
	} else {
		size += 39
	}
	if z := len(s.Addr.Zone()); z > 0 {
		size += 1 + z*2
	}
	size += len(s.Arr) * 4
	size += ((len(s.B32) + 4) / 5) * 8
	size += ((len(s.B64) + 2) / 3) * 4
	size += ((len(s.B64U) + 2) / 3) * 4
	size += int(s.BigF.Prec()) / 3
	size += s.BigI.BitLen() / 3
	size += (s.BigR.Num().BitLen() + s.BigR.Denom().BitLen()) / 3
	size += ((len(s.Fixed) + 2) / 3) * 4
	size += len(s.Hex) * 2
	if s.IP.To4() != nil {
		size += 15
	} else if len(s.IP) != 0 {
		size += 39
	} else {
		size += 2
	}
	size += ((len(s.MinB) + 2) / 3) * 4
	size += len(s.NS.String) * 2
	if s.Prefix.Addr().Is4() {
		size += 19
	} else {
		size += 43
	}
	size += len(s.URL.Scheme) + len(s.URL.Host)*3 + len(s.URL.Path)*3 + len(s.URL.RawQuery)*2 + len(s.URL.Fragment)*3 + len(s.URL.Opaque)*2
	if s.URL.User != nil {
		pw, _ := s.URL.User.Password()
		size += (len(s.URL.User.Username())+len(pw))*3 + 2
	}
	return size
}

func (s Stdlib) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"addr\":\""...)
	dst = ggen.AppendNetipAddr(dst, s.Addr)
	dst = append(dst, ",\"arr\":"...)
	if s.Arr == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '[')
		for i, b := range s.Arr {
			if i > 0 {
				dst = append(dst, ',')
			}
			dst = strconv.AppendUint(dst, uint64(b), 10)
		}
		dst = append(dst, ']')
	}
	dst = append(dst, ",\"b32\":"...)
	if s.B32 == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = base32.StdEncoding.AppendEncode(dst, s.B32)
		dst = append(dst, '"')
	}
	dst = append(dst, ",\"b64\":"...)
	if s.B64 == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = base64.StdEncoding.AppendEncode(dst, s.B64)
		dst = append(dst, '"')
	}
	dst = append(dst, ",\"b64u\":"...)
	if s.B64U == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = base64.URLEncoding.AppendEncode(dst, s.B64U)
		dst = append(dst, '"')
	}
	dst = append(dst, ",\"big_f\":\""...)
	dst = (&s.BigF).Append(dst, 'g', -1)
	dst = append(dst, "\",\"big_i\":"...)
	dst = (&s.BigI).Append(dst, 10)
	dst = append(dst, ",\"big_r\":\""...)
	if dst, err = (&s.BigR).AppendText(dst); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"d\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.D.String())
	dst = append(dst, ",\"d_milli\":"...)
	dst = strconv.AppendInt(dst, s.DMilli.Milliseconds(), 10)
	dst = append(dst, ",\"d_sec\":"...)
	if dst, err = ggen.AppendFloat(dst, s.DSec.Seconds(), 64); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"fixed\":\""...)
	dst = base64.StdEncoding.AppendEncode(dst, s.Fixed[:])
	dst = append(dst, '"')
	dst = append(dst, ",\"hex\":"...)
	if s.Hex == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = hex.AppendEncode(dst, s.Hex)
		dst = append(dst, '"')
	}
	dst = append(dst, ",\"ip\":\""...)
	if dst, err = s.IP.AppendText(dst); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"min_b\":"...)
	if s.MinB == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = base64.StdEncoding.AppendEncode(dst, s.MinB)
		dst = append(dst, '"')
	}
	dst = append(dst, ",\"ng\":"...)
	if !s.NG.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendBool(dst, s.NG.V)
	}
	dst = append(dst, ",\"ni\":"...)
	if !s.NI.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendInt(dst, int64(s.NI.Int16), 10)
	}
	dst = append(dst, ",\"ns\":"...)
	if !s.NS.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = ggen.AppendStringNoHTML(dst, s.NS.String)
	}
	dst = append(dst, ",\"prefix\":\""...)
	if dst, err = s.Prefix.AppendText(dst); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"t\":\""...)
	if dst, err = ggen.AppendRFC3339(dst, s.T, time.RFC3339Nano); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"t_date\":\""...)
	dst = s.TDate.AppendFormat(dst, time.DateOnly)
	dst = append(dst, "\",\"t_milli\":"...)
	dst = strconv.AppendInt(dst, s.TMilli.UnixMilli(), 10)
	dst = append(dst, ",\"t_unix\":"...)
	dst = ggen.AppendUnixSeconds(dst, s.TUnix)
	dst = append(dst, ",\"url\":\""...)
	dst = ggen.AppendURL(dst, s.URL)
	return append(dst, '}'), nil
}

