func (s More) JSONSize() int {
	size := 487
	size += len(s.Quoted) * 2
	size += ((len(s.B32H) + 4) / 5) * 8
	size += len(s.Note) * 2
	if s.PMap == nil {
		size += 4
	} else {
		size += 4
		size += len((*s.PMap)) * 24
		for k := range *s.PMap {
			size += len(k) * 2
		}
	}
	size += len(s.Structs) * 4
	for k, v := range s.Structs {
		size += len(k) * 2
		size += v.JSONSize()
	}
	if s.Zero != "" {
		size += 10
		size += len(s.Zero) * 2
	}
	return size
}

func (s More) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, '{')
	start := len(dst)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"a,b\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Quoted)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"b32h\":"...)
	if s.B32H == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = base32.HexEncoding.AppendEncode(dst, s.B32H)
		dst = append(dst, '"')
	}
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"d_micro\":"...)
	dst = strconv.AppendInt(dst, s.DMicro.Microseconds(), 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"d_nano\":"...)
	dst = strconv.AppendInt(dst, s.DNano.Nanoseconds(), 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"i16\":"...)
	dst = strconv.AppendInt(dst, int64(s.I16), 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"lvl\":"...)
	dst = strconv.AppendInt(dst, int64(int(s.Lvl)), 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"micro\":"...)
	dst = strconv.AppendInt(dst, s.Micro.UnixMicro(), 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"nano\":"...)
	dst = strconv.AppendInt(dst, s.Nano.UnixNano(), 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"note\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Note)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"nt\":"...)
	if !s.NT.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		if dst, err = ggen.AppendRFC3339(dst, s.NT.Time, time.RFC3339Nano); err != nil {
			return dst, err
		}
		dst = append(dst, '"')
	}
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"num\":"...)
	var bNum []byte
	bNum, err = json.Marshal(s.Num)
	if err != nil {
		return dst, err
	}
	dst = append(dst, bNum...)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"pmap\":"...)
	if s.PMap == nil {
		dst = append(dst, "null"...)
	} else {
		if (*s.PMap) == nil {
			dst = append(dst, "null"...)
		} else {
			dst = append(dst, '{')
			firstPMap := true
			for k, v := range *s.PMap {
				if firstPMap {
					firstPMap = false
					dst = append(dst, '"')
				} else {
					dst = append(dst, ",\""...)
				}
				dst = ggen.AppendStringNoHTML(dst, k)
				dst = append(dst, ':')
				dst = strconv.AppendInt(dst, int64(v), 10)
			}
			dst = append(dst, '}')
		}
	}
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"qu64\":\""...)
	dst = strconv.AppendUint(dst, s.QU64, 10)
	dst = append(dst, '"')
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"structs\":"...)
	if s.Structs == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '{')
		firstStructs := true
		for k, v := range s.Structs {
			if firstStructs {
				firstStructs = false
				dst = append(dst, '"')
			} else {
				dst = append(dst, ",\""...)
			}
			dst = ggen.AppendStringNoHTML(dst, k)
			dst = append(dst, ':')
			if dst, err = v.AppendJSON(dst); err != nil {
				return dst, err
			}
		}
		dst = append(dst, '}')
	}
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"u\":"...)
	dst = strconv.AppendUint(dst, uint64(s.U), 10)
	if len(dst) > start {
		dst = append(dst, ',')
	}
	dst = append(dst, "\"u16\":"...)
	dst = strconv.AppendUint(dst, uint64(s.U16), 10)
	if s.Zero != "" {
		if len(dst) > start {
			dst = append(dst, ',')
		}
		dst = append(dst, "\"zero\":\""...)
		dst = ggen.AppendStringNoHTML(dst, s.Zero)
	}
	return append(dst, '}'), nil
}

func (recv Pair) DecodeFrom(data []byte) (Pair, int, error) {
	return recv.decodeFromDepth(data, 0)
}

func (recv Pair) decodeFromDepth(data []byte, depth int) (result Pair, i int, err error) {
	result = recv
	if depth > 10000 { // runtime maxDepth
		return result, 0, ggen.ErrMaxDepth
	}
	seenLeft := false
	seenRight := false
	for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
		i++
	}
	if i >= len(data) || data[i] != '{' {
		return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
	}
	i++
	for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
		i++
	}
	if i < len(data) && data[i] == '}' {
		i++
		if !seenLeft {
			result.Left = nil
		}
		if !seenRight {
			result.Right = nil
		}
		return result, i, nil
	}
	for {
		var key string
		if i >= len(data) || data[i] != '"' {
			return result, i, ggen.NewParseErr("", i, ggen.ErrExpectString)
		}
		ke := i + 1
		for ke < len(data) && data[ke] != '"' && data[ke] != '\\' && data[ke] >= 0x20 && data[ke] < 0x80 {
			ke++
		}
		if ke < len(data) && data[ke] == '"' {
			key = unsafe.String(unsafe.SliceData(data[i+1:]), ke-i-1)
			i = ke + 1
		} else {
			key, i, err = ggen.String(data, i, true)
			if err != nil {
				return result, i, ggen.NewParseErr("", i, err)
			}
		}
		for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
			i++
		}
		if i >= len(data) || data[i] != ':' {
			return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
		}
		i++
		for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
			i++
		}
		switch key {
		case "left":
			if seenLeft {
				return result, i, &ggen.DuplicateKeyError{Pos: i, Path: []string{"left"}}
			}
			seenLeft = true
			if i < len(data) && data[i] == 'n' {
				if i+4 > len(data) || data[i+1] != 'u' || data[i+2] != 'l' || data[i+3] != 'l' {
					return result, i, ggen.NewParseErr("left", i, ggen.ErrBadLiteral)
				}
				i += 4
				result.Left = nil
				break
			}
			var v Node
			if result.Left != nil {
				v = (*result.Left)
			}
			var consumed int
			v, consumed, err = v.decodeFromDepth(data[i:], depth+1)
			i += consumed
			if err != nil {
				return result, i, ggen.NewParseErrShift("left", i, consumed, err)
			}
			if result.Left == nil {
				result.Left = new(v)
			} else {
				(*result.Left) = v
			}
		case "right":
			if seenRight {
				return result, i, &ggen.DuplicateKeyError{Pos: i, Path: []string{"right"}}
			}
			seenRight = true
			if i < len(data) && data[i] == 'n' {
				if i+4 > len(data) || data[i+1] != 'u' || data[i+2] != 'l' || data[i+3] != 'l' {
					return result, i, ggen.NewParseErr("right", i, ggen.ErrBadLiteral)
				}
				i += 4
				result.Right = nil
				break
			}
			var v Node
			if result.Right != nil {
				v = (*result.Right)
			}
			var consumed int
			v, consumed, err = v.decodeFromDepth(data[i:], depth+1)
			i += consumed
			if err != nil {
				return result, i, ggen.NewParseErrShift("right", i, consumed, err)
			}
			if result.Right == nil {
				result.Right = new(v)
			} else {
				(*result.Right) = v
			}
		default:
			return result, i, &ggen.UnknownKeyError{Pos: i, Path: []string{key}}
		}
		for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
			i++
		}
		if i >= len(data) {
			return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
		}
		if data[i] == ',' {
			i++
			for i < len(data) && data[i] <= ' ' && (data[i] == ' ' || data[i] == '\t' || data[i] == '\n' || data[i] == '\r') {
				i++
			}
			continue
		}
		if data[i] == '}' {
			i++
			if !seenLeft {
				result.Left = nil
			}
			if !seenRight {
				result.Right = nil
			}
			return result, i, nil
		}
		return result, i, ggen.NewParseErr("", i, ggen.ErrBadObject)
	}
}

func (recv Pair) DecodeFromStream(s *ggen.Stream) (Pair, error) {
	return recv.decodeFromStreamDepth(s, 0)
}

func (recv Pair) decodeFromStreamDepth(s *ggen.Stream, depth int) (result Pair, err error) {
	result = recv
	if depth > 10000 { // runtime maxDepth
		return result, ggen.ErrMaxDepth
	}
	seenLeft := false
	seenRight := false
	err = s.ObjectOpen()
	if err != nil {
		return result, ggen.NewParseErr("", s.Offset(), err)
	}
	err = s.SkipSpace()
	if err != nil {
		return result, ggen.NewParseErr("", s.Offset(), err)
	}
	if s.Pos >= len(s.Bytes()) {
		if err = s.ReadMore(s.Pos); err != nil {
			return result, ggen.NewParseErr("", s.Offset(), ggen.NotEOF(err, ggen.ErrExpectString))
		}
		s.Pos = 0
	}
	if s.Bytes()[s.Pos] == '}' {
		s.Pos++
		if !seenLeft {
			result.Left = nil
		}
		if !seenRight {
			result.Right = nil
		}
		return result, nil
	}
	for {
		var key string
		key, err = s.KeyView(true)
		if err != nil {
			return result, ggen.NewParseErr("", s.Offset(), err)
		}
		switch key {
		case "left":
			err = s.ConsumeColon()
			if err != nil {
				return result, ggen.NewParseErr("left", s.Offset(), err)
			}
			if seenLeft {
				return result, &ggen.DuplicateKeyError{Pos: s.Offset(), Path: []string{"left"}}
			}
			seenLeft = true
			if s.Pos >= len(s.Bytes()) {
				if err = s.ReadMore(0); err != nil {
					return result, ggen.NewParseErr("left", s.Offset(), ggen.NotEOF(err, ggen.ErrBadObject))
				}
			}
			if s.Bytes()[s.Pos] == 'n' {
				for ki := 1; ki < 4; ki++ {
					if s.Pos+ki >= len(s.Bytes()) {
						if err = s.ReadMore(0); err != nil {
							return result, ggen.NewParseErr("left", s.Offset(), ggen.NotEOF(err, ggen.ErrBadLiteral))
						}
					}
					if s.Bytes()[s.Pos+ki] != "null"[ki] {
						return result, ggen.NewParseErr("left", s.Offset(), ggen.ErrBadLiteral)
					}
				}
				s.Pos += 4
				result.Left = nil
				break
			}
			var v Node
			if result.Left != nil {
				v = (*result.Left)
			}
			v, err = v.decodeFromStreamDepth(s, depth+1)
			if err != nil {
				return result, ggen.NewParseErr("left", s.Offset(), err)
			}
			if result.Left == nil {
				result.Left = new(v)
			} else {
				(*result.Left) = v
			}
		case "right":
			err = s.ConsumeColon()
			if err != nil {
				return result, ggen.NewParseErr("right", s.Offset(), err)
			}
			if seenRight {
				return result, &ggen.DuplicateKeyError{Pos: s.Offset(), Path: []string{"right"}}
			}
			seenRight = true
			if s.Pos >= len(s.Bytes()) {
				if err = s.ReadMore(0); err != nil {
					return result, ggen.NewParseErr("right", s.Offset(), ggen.NotEOF(err, ggen.ErrBadObject))
				}
			}
			if s.Bytes()[s.Pos] == 'n' {
				for ki := 1; ki < 4; ki++ {
					if s.Pos+ki >= len(s.Bytes()) {
						if err = s.ReadMore(0); err != nil {
							return result, ggen.NewParseErr("right", s.Offset(), ggen.NotEOF(err, ggen.ErrBadLiteral))
						}
					}
					if s.Bytes()[s.Pos+ki] != "null"[ki] {
						return result, ggen.NewParseErr("right", s.Offset(), ggen.ErrBadLiteral)
					}
				}
				s.Pos += 4
				result.Right = nil
				break
			}
			var v Node
			if result.Right != nil {
				v = (*result.Right)
			}
			v, err = v.decodeFromStreamDepth(s, depth+1)
			if err != nil {
				return result, ggen.NewParseErr("right", s.Offset(), err)
			}
			if result.Right == nil {
				result.Right = new(v)
			} else {
				(*result.Right) = v
			}
		default:
			ownKey := strings.Clone(key)
			err = s.ConsumeColon()
			if err != nil {
				return result, ggen.NewParseErr(ownKey, s.Offset(), err)
			}
			return result, &ggen.UnknownKeyError{Pos: s.Offset(), Path: []string{ownKey}}
		}

		err = s.SkipSpace()
		if err != nil {
			return result, ggen.NewParseErr("", s.Offset(), err)
		}
		if s.Pos >= len(s.Bytes()) {
			if err = s.ReadMore(s.Pos); err != nil {
				return result, ggen.NewParseErr("", s.Offset(), ggen.NotEOF(err, ggen.ErrBadObject))
			}
			s.Pos = 0
		}
		c := s.Bytes()[s.Pos]
		if c == ',' {
			s.Pos++
			err = s.SkipSpace()
			if err != nil {
				return result, ggen.NewParseErr("", s.Offset(), err)
			}
			continue
		}
		if c == '}' {
			s.Pos++
			if !seenLeft {
				result.Left = nil
			}
			if !seenRight {
				result.Right = nil
			}
			return result, nil
		}
		return result, ggen.NewParseErr("", s.Offset(), ggen.ErrBadObject)
	}
}

func (s Pair) JSONSize() int {
	size := 18
	if s.Left == nil {
		size += 4
	} else {
		size += (*s.Left).JSONSize()
	}
	if s.Right == nil {
		size += 4
	} else {
		size += (*s.Right).JSONSize()
	}
	return size
}

func (s Pair) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"left\":"...)
	if s.Left == nil {
		dst = append(dst, "null"...)
	} else {
		if dst, err = (*s.Left).AppendJSON(dst); err != nil {
			return dst, err
		}
	}
	dst = append(dst, ",\"right\":"...)
	if s.Right == nil {
		dst = append(dst, "null"...)
	} else {
		if dst, err = (*s.Right).AppendJSON(dst); err != nil {
			return dst, err
		}
	}
	return append(dst, '}'), nil
}
